260	    private ResponseEntity<?> idempotent(String opType, String requestId, Object payload,
261	                                         java.util.function.Supplier<ServiceResult> action) {
262	        IdempotentOutcome outcome = idempotency.run(opType, requestId, payload, action);
263	        if (outcome.first()) {
264	            return ResponseEntity.status(outcome.status()).body(outcome.firstBody());
265	        }
266	        return ResponseEntity.status(outcome.status())
267	                .contentType(MediaType.APPLICATION_JSON)
268	                .body(outcome.replayBody());
269	    }
270	
271	    private Map<String, Object> payload(Object body, Object... kv) {
272	        Map<String, Object> map = new LinkedHashMap<>();
273	        map.put("body", body);
274	        for (int i = 0; i + 1 < kv.length; i += 2) {
275	            map.put((String) kv[i], kv[i + 1]);
276	        }
277	        return map;
278	    }
