1	package com.example.rebate.service;
2	
3	import com.example.rebate.domain.BatchStatus;
4	import com.example.rebate.domain.Doubt;
5	import com.example.rebate.repo.BatchRepository;
6	import com.example.rebate.repo.CheckDetailRepository;
7	import com.example.rebate.repo.DoubtRepository;
8	import com.example.rebate.support.TimeService;
9	import com.example.rebate.web.ConflictException;
10	import com.example.rebate.web.NotFoundException;
11	import com.example.rebate.web.UnprocessableException;
12	import com.example.rebate.web.dto.CheckResponse;
13	import java.util.List;
14	import org.springframework.stereotype.Service;
15	import org.springframework.transaction.annotation.Transactional;
16	
17	/**
18	 * 疑点处理：提交补充说明后须复核确认方可解除。
19	 */
20	@Service
21	public class DoubtService {
22	
23	    private final DoubtRepository doubtRepo;
24	    private final BatchRepository batchRepo;
25	    private final CheckDetailRepository detailRepo;
26	    private final TimeService timeService;
27	
28	    public DoubtService(DoubtRepository doubtRepo, BatchRepository batchRepo,
29	                        CheckDetailRepository detailRepo, TimeService timeService) {
30	        this.doubtRepo = doubtRepo;
31	        this.batchRepo = batchRepo;
32	        this.detailRepo = detailRepo;
33	        this.timeService = timeService;
34	    }
35	
36	    /**
37	     * 提交补充说明（OPEN -> EXPLAINED）。重复提交幂等返回当前状态，不改变说明内容。
38	     */
39	    @Transactional
40	    public CheckResponse explain(String batchNo, long doubtId, String explanation) {
41	        Doubt doubt = loadDoubt(batchNo, doubtId);
42	        switch (doubt.status()) {
43	            case OPEN -> doubtRepo.submitExplanation(doubtId, explanation, timeService.now());
44	            case EXPLAINED, RESOLVED -> {
45	                // 已提交/已复核：重复提交不覆盖，返回当前视图（同键重放也走存档）。
46	            }
47	        }
48	        return currentView(batchNo, doubt.batchId());
49	    }
50	
51	    /**
52	     * 复核确认（EXPLAINED -> RESOLVED）。未提交说明不得复核。全部疑点解除后批次回到 CHECKED。
53	     */
54	    @Transactional
55	    public CheckResponse review(String batchNo, long doubtId) {
56	        Doubt doubt = loadDoubt(batchNo, doubtId);
57	        if (doubt.status() == com.example.rebate.domain.DoubtStatus.OPEN) {
58	            throw new UnprocessableException("疑点 " + doubtId + " 尚未提交补充说明，不能复核确认");
59	        }
60	        if (doubt.status() == com.example.rebate.domain.DoubtStatus.EXPLAINED) {
61	            doubtRepo.reviewResolve(doubtId, timeService.now());
62	        }
63	        // RESOLVED 重复复核幂等。
64	        refreshBatchStatus(doubt.batchId());
65	        return currentView(batchNo, doubt.batchId());
66	    }
67	
68	    private Doubt loadDoubt(String batchNo, long doubtId) {
69	        var batch = batchRepo.findByNo(batchNo)
70	                .orElseThrow(() -> new NotFoundException("批次不存在: " + batchNo));
71	        if (batch.status() == BatchStatus.VOID) {
72	            throw new ConflictException("批次已作废: " + batchNo);
73	        }
74	        List<Doubt> doubts = doubtRepo.findById(doubtId);
75	        Doubt doubt = doubts.stream().findFirst()
76	                .orElseThrow(() -> new NotFoundException("疑点不存在: " + doubtId));
77	        if (doubt.batchId() != batch.id()) {
78	            throw new NotFoundException("疑点 " + doubtId + " 不属于批次 " + batchNo);
79	        }
80	        return doubt;
81	    }
82	
83	    /**
84	     * 若全部疑点均 RESOLVED，批次由 DOUBTFUL 回到 CHECKED；否则保持 DOUBTFUL。
85	     */
86	    private void refreshBatchStatus(long batchId) {
87	        boolean hasUnresolved = !doubtRepo.findUnresolvedByBatchId(batchId).isEmpty();
88	        if (!hasUnresolved) {
89	            var batch = batchRepo.findById(batchId).orElseThrow();
90	            if (batch.status() == BatchStatus.DOUBTFUL) {
91	                batchRepo.updateStatus(batchId, BatchStatus.CHECKED,
92	                        batch.totalDeclaredTax(), timeService.now());
93	            }
94	        }
95	    }
96	
97	    private CheckResponse currentView(String batchNo, long batchId) {
98	        var batch = batchRepo.findById(batchId).orElseThrow();
99	        return BatchViews.check(batch,
100	                detailRepo.findByBatchId(batchId), doubtRepo.findByBatchId(batchId));
101	    }
102	}
