28	/**
29	 * 批次查询与复算：文库版本取值、校验明细、核销差异均可按落库输入重新计算并比对。
30	 */
31	@Service
32	public class QueryService {
33	
34	    private final BatchRepository batchRepo;
35	    private final CheckDetailRepository detailRepo;
36	    private final DoubtRepository doubtRepo;
37	    private final TreasuryWriteoffRepository writeoffRepo;
38	    private final RateLibraryRepository rateRepo;
39	    private final InputInvoiceRepository invoiceRepo;
40	
41	    public QueryService(BatchRepository batchRepo,
42	                        CheckDetailRepository detailRepo,
43	                        DoubtRepository doubtRepo,
44	                        TreasuryWriteoffRepository writeoffRepo,
45	                        RateLibraryRepository rateRepo,
46	                        InputInvoiceRepository invoiceRepo) {
47	        this.batchRepo = batchRepo;
48	        this.detailRepo = detailRepo;
49	        this.doubtRepo = doubtRepo;
50	        this.writeoffRepo = writeoffRepo;
51	        this.rateRepo = rateRepo;
52	        this.invoiceRepo = invoiceRepo;
53	    }
54	
55	    /**
56	     * 批次状态视图。
57	     */
58	    @Transactional(readOnly = true)
59	    public BatchView getBatch(String batchNo) {
60	        return BatchViews.batch(load(batchNo));
61	    }
62	
63	    /**
64	     * 批次校验明细与疑点视图。
65	     */
66	    @Transactional(readOnly = true)
67	    public CheckResponse getCheck(String batchNo) {
68	        DeclarationBatch batch = load(batchNo);
69	        return BatchViews.check(batch,
70	                detailRepo.findByBatchId(batch.id()), doubtRepo.findByBatchId(batch.id()));
71	    }
72	
73	    /**
74	     * 复算校验明细：按批次申报日（UTC）重新取有效文库版本，重算计税依据与换汇成本，
75	     * 并与首次落库值逐项比对（含版本号、税率、结果）。
76	     */
77	    @Transactional(readOnly = true)
78	    public RecalcResponse recalcCheck(String batchNo) {
79	        DeclarationBatch batch = load(batchNo);
80	        List<Map<String, Object>> items = new ArrayList<>();
81	        boolean consistent = true;
82	        for (CheckDetail d : detailRepo.findByBatchId(batch.id())) {
83	            RateLibrary resolved = rateRepo
84	                    .findEffectiveVersion(d.productCode(), batch.declareDate()).orElse(null);
85	            Map<String, Object> item = new LinkedHashMap<>();
86	            item.put("detailId", d.id());
87	            item.put("declarationNo", d.declarationNo());
88	            item.put("productCode", d.productCode());
89	
90	            boolean itemOk = true;
91	            long matchedInvoices = invoiceRepo.findByDeclarationNo(d.declarationNo()).stream()
92	                    .filter(i -> i.productCode().equals(d.productCode()))
93	                    .count();
94	            if (matchedInvoices == 0) {
95	                itemOk = "MATCH_MISSING".equals(d.doubtType()) && d.versionNo() == null;
96	                item.put("recalcMatchedInvoices", 0);
97	            } else if (resolved == null) {
98	                item.put("recalcVersionNo", null);
99	                itemOk = d.versionNo() == null && "RATE_NOT_FOUND".equals(d.doubtType());
100	            } else {
101	                BigDecimal recalcBasis =
102	                        RebateCalculator.taxBasis(d.fobAmount(), resolved.rebateRate());
103	                BigDecimal recalcCost =
104	                        RebateCalculator.exchangeCost(recalcBasis, d.fobUsd());
105	                boolean inRange = RebateCalculator.exchangeCostInRange(recalcCost);
106	                item.put("recalcVersionNo", resolved.versionNo());
107	                item.put("recalcRebateRate", resolved.rebateRate());
108	                item.put("recalcTaxBasis", recalcBasis);
109	                item.put("recalcExchangeCost", recalcCost);
110	                item.put("storedVersionNo", d.versionNo());
111	                item.put("storedTaxBasis", d.taxBasis());
112	                item.put("storedExchangeCost", d.exchangeCost());
113	                itemOk = resolved.versionNo().equals(d.versionNo())
114	                        && eq(recalcBasis, d.taxBasis())
115	                        && eq(recalcCost, d.exchangeCost())
116	                        && inRange == (d.result() == com.example.rebate.domain.CheckResult.PASS);
117	                if (!inRange) {
118	                    itemOk = itemOk && "EXCHANGE_COST_OUT_OF_RANGE".equals(d.doubtType());
119	                }
120	            }
121	            item.put("match", itemOk);
122	            consistent &= itemOk;
123	            items.add(item);
124	        }
125	        return new RecalcResponse("CHECK_DETAIL:" + batchNo, consistent, items);
126	    }
127	
128	    /**
129	     * 复算核销差异：以落库申报税额与到账金额重算差额、比例与一致性，逐条比对。
130	     */
131	    @Transactional(readOnly = true)
132	    public RecalcResponse recalcWriteoffs(String batchNo) {
133	        DeclarationBatch batch = load(batchNo);
134	        List<Map<String, Object>> items = new ArrayList<>();
135	        boolean consistent = true;
136	        for (TreasuryWriteoff w : writeoffRepo.findByBatchId(batch.id())) {
137	            BigDecimal recalcDiff =
138	                    RebateCalculator.diffAmount(w.declaredTax(), w.receivedAmount());
139	            BigDecimal recalcRatio =
140	                    RebateCalculator.diffRatio(w.declaredTax(), w.receivedAmount());
141	            boolean recalcConsistent = RebateCalculator.diffConsistent(recalcRatio);
142	            boolean itemOk = eq(recalcDiff, w.diffAmount())
143	                    && eq(recalcRatio, w.diffRatio())
144	                    && recalcConsistent == w.consistent()
145	                    && w.manualFlag() == !recalcConsistent;
146	            Map<String, Object> item = new LinkedHashMap<>();
147	            item.put("writeoffId", w.id());
148	            item.put("treasurySerial", w.treasurySerial());
149	            item.put("recalcDiffAmount", recalcDiff);
150	            item.put("storedDiffAmount", w.diffAmount());
151	            item.put("recalcDiffRatio", recalcRatio);
152	            item.put("storedDiffRatio", w.diffRatio());
153	            item.put("recalcConsistent", recalcConsistent);
154	            item.put("storedConsistent", w.consistent());
155	            item.put("match", itemOk);
156	            consistent &= itemOk;
157	            items.add(item);
158	        }
159	        return new RecalcResponse("TREASURY_WRITEOFF:" + batchNo, consistent, items);
160	    }
