33	 *
34	 * <p>整个关联校验在同一事务内：任一报关单已被其它有效批次占用、不存在、缺税率等，
35	 * 已插入的批次/占用/明细全部回滚。</p>
36	 */
37	@Service
38	public class CheckService {
39	
40	    static final String DOUBT_RATE_NOT_FOUND = "RATE_NOT_FOUND";
41	    static final String DOUBT_MATCH_MISSING = "MATCH_MISSING";
42	    static final String DOUBT_EXCHANGE_COST = "EXCHANGE_COST_OUT_OF_RANGE";
43	
44	    private final BatchRepository batchRepo;
45	    private final CustomsDeclarationRepository customsRepo;
46	    private final InputInvoiceRepository invoiceRepo;
47	    private final RateLibraryRepository rateRepo;
48	    private final CheckDetailRepository detailRepo;
49	    private final DoubtRepository doubtRepo;
50	    private final TimeService timeService;
51	
52	    public CheckService(BatchRepository batchRepo,
53	                        CustomsDeclarationRepository customsRepo,
54	                        InputInvoiceRepository invoiceRepo,
55	                        RateLibraryRepository rateRepo,
56	                        CheckDetailRepository detailRepo,
57	                        DoubtRepository doubtRepo,
58	                        TimeService timeService) {
59	        this.batchRepo = batchRepo;
60	        this.customsRepo = customsRepo;
61	        this.invoiceRepo = invoiceRepo;
62	        this.rateRepo = rateRepo;
63	        this.detailRepo = detailRepo;
64	        this.doubtRepo = doubtRepo;
65	        this.timeService = timeService;
66	    }
67	
68	    /**
69	     * 执行关联校验并返回批次校验视图。
70	     */
71	    @Transactional
