3	import com.example.rebate.domain.IdempotentRecord;
4	import java.sql.ResultSet;
5	import java.sql.SQLException;
6	import java.sql.Timestamp;
7	import java.time.Instant;
8	import java.util.List;
9	import org.springframework.dao.DuplicateKeyException;
10	import org.springframework.jdbc.core.JdbcTemplate;
11	import org.springframework.jdbc.core.RowMapper;
12	import org.springframework.stereotype.Repository;
13	
14	/**
15	 * requestId 幂等记录数据访问。
16	 *
17	 * <p>以 request_id 为主键先插入占坑行，保证同键并发请求只有一个进入实际业务；
18	 * 指纹不同返回 409，指纹相同返回首次结果。</p>
19	 */
20	@Repository
21	public class IdempotentRecordRepository {
22	
23	    private static final RowMapper<IdempotentRecord> MAPPER = new RecordRowMapper();
24	
25	    private final JdbcTemplate jdbc;
26	
27	    public IdempotentRecordRepository(JdbcTemplate jdbc) {
28	        this.jdbc = jdbc;
29	    }
30	
31	    /**
32	     * 尝试占坑。
33	     *
34	     * @return {@code true} 首次占位成功，调用方执行业务；{@code false} requestId 已存在
35	     */
36	    public boolean tryAcquire(String requestId, String opType, String fingerprint, Instant now) {
37	        try {
38	            jdbc.update("""
39	                    INSERT INTO t_idempotent_record
40	                        (request_id, op_type, fingerprint, response_status, response_body, created_at)
41	                    VALUES (?, ?, ?, NULL, NULL, ?)
42	                    """,
43	                    requestId, opType, fingerprint, Timestamp.from(now));
44	            return true;
45	        } catch (DuplicateKeyException e) {
46	            return false;
47	        }
48	    }
49	
50	    /**
51	     * 回写首次执行结果。
52	     */
53	    public void complete(String requestId, int status, String body, Instant now) {
54	        jdbc.update("""
55	                UPDATE t_idempotent_record
56	                SET response_status = ?, response_body = ?, completed_at = ?
57	                WHERE request_id = ?
58	                """,
59	                status, body, Timestamp.from(now), requestId);
60	    }
61	
62	    /**
63	     * 查询幂等记录。
64	     */
65	    public List<IdempotentRecord> find(String requestId) {
66	        return jdbc.query(
67	                "SELECT request_id, op_type, fingerprint, response_status, response_body, "
68	                        + "created_at, completed_at FROM t_idempotent_record WHERE request_id = ?",
69	                MAPPER, requestId);
70	    }
71	
72	    private static final class RecordRowMapper implements RowMapper<IdempotentRecord> {
73	        @Override
74	        public IdempotentRecord mapRow(ResultSet rs, int rowNum) throws SQLException {
75	            Object status = rs.getObject("response_status");
76	            return new IdempotentRecord(
77	                    rs.getString("request_id"),
78	                    rs.getString("op_type"),
79	                    rs.getString("fingerprint"),
80	                    status == null ? null : ((Number) status).intValue(),
81	                    rs.getString("response_body"),
82	                    rs.getTimestamp("created_at").toInstant(),
83	                    toInstant(rs.getTimestamp("completed_at")));
84	        }
85	
86	        private static Instant toInstant(Timestamp ts) {
87	            return ts == null ? null : ts.toInstant();
88	        }
89	    }
90	}
